class TaskStatus(Enum):
    PENDING = "PENDING"
    RUNNING = "RUNNING"
    COMPLETED = "COMPLETED"
    FAILED = "FAILED"

@dataclass
class Task:
    id: str
    name: str
    command: str
    depends_on: List[str] = field(default_factory=list)
    status: TaskStatus = TaskStatus.PENDING
    output: Optional[str] = None
    error: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {"id": self.id, "name": self.name, "command": self.command, "depends_on": self.depends_on, "status": self.status.value, "output": self.output, "error": self.error}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Task":
        return cls(id=data["id"], name=data["name"], command=data["command"], depends_on=data.get("depends_on", []), status=TaskStatus(data.get("status", "PENDING")), output=data.get("output"), error=data.get("error"))

class TaskStore:
    def __init__(self, storage_path: str):
        self.storage_path = storage_path

    def save_tasks(self, tasks: List[Task]) -> None:
        target_dir = os.path.dirname(os.path.abspath(self.storage_path)) or "."
        os.makedirs(target_dir, exist_ok=True)
        fd, temp_path = tempfile.mkstemp(dir=target_dir, prefix="store_", suffix=".tmp")
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                data = [t.to_dict() for t in tasks]
                json.dump(data, f, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_path, self.storage_path)
        except Exception:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            raise

    def load_tasks(self) -> List[Task]:
        if not os.path.exists(self.storage_path):
            return []
        with open(self.storage_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return [Task.from_dict(item) for item in data]

    def get_task(self, task_id: str) -> Optional[Task]:
        for task in self.load_tasks():
            if task.id == task_id:
                return task
        return None

class CycleError(Exception):
    pass

class DependencyGraph:
    def __init__(self, tasks: List[Task]):
        self.tasks = {t.id: t for t in tasks}
        self.adj = defaultdict(list)
        self.in_degree = {t.id: 0 for t in tasks}
        for task in tasks:
            for dep in task.depends_on:
                if dep in self.tasks:
                    self.adj[dep].append(task.id)
                    self.in_degree[task.id] += 1

    def has_cycle(self) -> bool:
        in_deg = dict(self.in_degree)
        queue = deque([tid for tid, deg in in_deg.items() if deg == 0])
        visited_count = 0
        while queue:
            curr = queue.popleft()
            visited_count += 1
            for neighbor in self.adj[curr]:
                in_deg[neighbor] -= 1
                if in_deg[neighbor] == 0:
                    queue.append(neighbor)
        return visited_count != len(self.tasks)

    def get_execution_batches(self) -> List[List[Task]]:
        if self.has_cycle():
            raise CycleError("Cycle detected in dependency graph")
        in_deg = dict(self.in_degree)
        queue = deque([tid for tid, deg in in_deg.items() if deg == 0])
        batches = []
        while queue:
            current_batch = list(queue)
            queue.clear()
            batch_tasks = [self.tasks[tid] for tid in current_batch]
            batches.append(batch_tasks)
            for tid in current_batch:
                for neighbor in self.adj[tid]:
                    in_deg[neighbor] -= 1
                    if in_deg[neighbor] == 0:
                        queue.append(neighbor)
        return batches

@dataclass
class PipelineResult:
    total_tasks: int
    succeeded: int
    failed: int
    duration_ms: float
    tasks: List[Task] = field(default_factory=list)

class PipelineExecutor:
    def __init__(self, store: Optional[TaskStore] = None):
        self.store = store

    def execute_task(self, task: Task) -> Task:
        task.status = TaskStatus.RUNNING
        start = time.perf_counter()
        proc = subprocess.run(task.command, shell=True, capture_output=True, text=True)
        if proc.returncode == 0:
            task.status = TaskStatus.COMPLETED
            task.output = proc.stdout.strip()
            task.error = None
        else:
            task.status = TaskStatus.FAILED
            task.output = proc.stdout.strip()
            task.error = proc.stderr.strip() or f"Process exited with code {proc.returncode}"
        return task

    def run_pipeline(self, tasks: List[Task]) -> PipelineResult:
        start_time = time.perf_counter()
        graph = DependencyGraph(tasks)
        batches = graph.get_execution_batches()
        failed_ids = set()
        all_tasks = {t.id: t for t in tasks}
        for batch in batches:
            for task in batch:
                has_failed_dep = any(dep in failed_ids for dep in task.depends_on)
                if has_failed_dep:
                    task.status = TaskStatus.FAILED
                    task.error = "Prerequisite dependency failed"
                    failed_ids.add(task.id)
                else:
                    self.execute_task(task)
                    if task.status == TaskStatus.FAILED:
                        failed_ids.add(task.id)
        if self.store:
            self.store.save_tasks(list(all_tasks.values()))
        duration_ms = (time.perf_counter() - start_time) * 1000.0
        succeeded = sum(1 for t in all_tasks.values() if t.status == TaskStatus.COMPLETED)
        failed = sum(1 for t in all_tasks.values() if t.status == TaskStatus.FAILED)
        return PipelineResult(total_tasks=len(all_tasks), succeeded=succeeded, failed=failed, duration_ms=duration_ms, tasks=list(all_tasks.values()))
